protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve "Discriminator" property name used by existing documents (EF9 default is "$type")
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve "Blog|1" id format used by existing documents (EF9 default omits discriminator)
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB threw at startup in EF9; manage indexing via Azure portal/Bicep
}

